local b=""
local M={}
local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i=1,#A do M[A:sub(i,i)]=i-1 end
local o,cnt,acc,bits={},0,0,0
for i=1,#b do
local v=M[b:sub(i,i)]
if v then
acc=acc*64+v
bits=bits+6
while bits>=8 do
bits=bits-8
cnt=cnt+1
o[cnt]=string.char(math.floor(acc/(2^bits))%256)
end
acc=acc%(2^bits)
end
end
local d=table.concat(o)
local out,cnt2={},0
local i=1
while i<=#d do
local t=d:byte(i)
i=i+1
if t<128 then
local k=t+1
for q=1,k do
cnt2=cnt2+1
out[cnt2]=d:sub(i,i)
i=i+1
end
else
local len=t-128+3
local off=d:byte(i)+d:byte(i+1)*256
i=i+2
for q=0,len-1 do
cnt2=cnt2+1
out[cnt2]=out[cnt2-off]
end
end
end
local code=table.concat(out)
local f=loadstring or load
local fn=f(code)
if fn then fn() else print("[附魔领取] 解密失败") end
